        console.error("Error: No se encontró la tabla de cálculo.");
        return;
    }

    // Función auxiliar para recalcular todas las celdas con fórmulas
    const recalculateAllFormulaCells = () => {
        document.querySelectorAll('[data-cell]').forEach(cell => {
            const formula = cell.innerText.trim();
            if (formula && formula.startsWith('=')) {
                calculateCell(cell);
            }
        });
    };

    // Usamos event delegation para escuchar en toda la tabla, 
