        return; // No actualizar si hay error
    }

    // Actualizar el contenido visible de la celda con el resultado calculado
    if (result !== null && !isNaN(result)) {
        cellElement.innerText = result;
        cellElement.dataset.isCalculated = 'true'; 
    } else if (formulaBody) {
