function setupColumnSelectionListener() {
    const colHeaders = document.querySelectorAll('.col-header');
    let selectedColElement = null;

    // Función que maneja la selección de una columna al hacer clic en su letra
    const handleHeaderClick = (event) => {
        const clickedHeader = event.currentTarget;
        const colIndex = parseInt(clickedHeader.getAttribute('data-col-index'));

        if (selectedColElement === clickedHeader) {
            // Deseleccionar si se hace clic en la misma columna
            selectedColElement.classList.remove('selected');
            selectedColElement = null;
            console.log("Columna deseleccionada.");
            return;
        }

        // Limpiar selección anterior
        if (selectedColElement) {
            selectedColElement.classList.remove('selected');
        }

        // Establecer nueva selección
        selectedColElement = clickedHeader;
        selectedColElement.classList.add('selected');
        console.log(`Columna seleccionada: ${clickedHeader.innerText}, Índice: ${colIndex}`);
    };

    colHeaders.forEach(header => {
        header.addEventListener('click', handleHeaderClick);
    });
}
