    const rows = document.getElementById('spreadsheet').querySelector('tbody').querySelectorAll('tr');
    rows.forEach(row => {
        // Buscar el TD que corresponde a esta columna (el índice es relativo al tbody)
        const cellToHide = row.querySelector(`td:nth-child(${colIndex + 2})`); // +2 porque la primera celda es el row-label
        if (cellToHide) {
            cellToHide.style.display = 'none';
            // Limpiar datos de localStorage al eliminar columna
            const cellId = cellToHide.getAttribute('data-cell');
            localStorage.removeItem(`spreadsheet_${cellId}`);
        }
    });

    console.log(`Columna ${selectedColHeader.innerText} eliminada.`);
}
