```javascript
/**
 * Global state variables for selection management (assuming they were intended to be global or managed by the scope).
 */
let selectedRowIndex = null;
let selectedColIndex = null; // 0-indexed column index (A=0, B=1, ...)

// --- Column Selection Management ---

/**
 * Sets up event listeners for selecting columns via their header letters.
 */
function setupColumnSelectionListener() {
    const colHeaders = document.querySelectorAll('.col-header');

    // Limpiar cualquier listener anterior si se llama varias veces (aunque no debería pasar aquí)
    colHeaders.forEach(header => {
        header.removeEventListener('click', handleSelectColumn);
    });

    colHeaders.forEach(header => {
        header.addEventListener('click', handleSelectColumn);
    });
}

/**
 * Handles the selection of a column header (the letter).
 * @param {Event} event 
 */
function handleSelectColumn(event) {
    const clickedHeader = event.currentTarget;
    // Obtener el índice de la columna del atributo data-col-index
    selectedColIndex = parseInt(clickedHeader.getAttribute('data-col-index'));

    console.log(`Columna seleccionada: ${clickedHeader.innerText} (Índice: ${selectedColIndex})`);

    // Lógica visual para resaltar el encabezado seleccionado
    document.querySelectorAll('.col-header').forEach(h => h.classList.remove('selected-column'));
    clickedHeader.classList.add('selected-column');
}


/**
 * Clears the content of all cells in the currently selected column.
 */
function clearSelectedColumn() {
    if (isNaN(selectedColIndex) || selectedColIndex === null) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }

    const colHeader = document.querySelector(`.col-header[data-col-index="${selectedColIndex}"]`);
    if (!colHeader) return;

    // Seleccionar todas las celdas de datos (TD) en esa columna
    const cells = document.querySelectorAll(`#spreadsheet tbody td:nth-child(${selectedColIndex + 2})`); // +2 porque el primer TD es para row-label

    cells.forEach(cell => {
        // Limpiar contenido y resetear atributos de cálculo/color
        cell.innerText = '';
        delete cell.dataset.isCalculated;
        cell.style.backgroundColor = ''; 
    });

    console.log(`Contenido de la columna ${colHeader.innerText} borrado.`);
}


/**
 * Changes the background color of all cells in the currently selected column.
 */
function applyColorToSelectedColumn(color) {
    if (isNaN(selectedColIndex) || selectedColIndex === null) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }

    const colHeader = document.querySelector(`.col-header[data-col-index="${selectedColIndex}"]`);
    if (!colHeader) return;

    // Seleccionar todas las celdas de datos (TD) en esa columna
    const cells = document.querySelectorAll(`#spreadsheet tbody td:nth-child(${selectedColIndex + 2})`);

    cells.forEach(cell => {
        cell.style.backgroundColor = color;
    });

    console.log(`Color de fondo aplicado a la columna ${colHeader.innerText}: ${color}`);
}


/**
 * Deletes the selected column (header and all cells).
 */
function deleteSelectedColumn() {
    if (isNaN(selectedColIndex) || selectedColIndex === null) {
        alert("Por favor, selecciona una columna primero.");
        return;
    }

    const colHeader = document.querySelector(`.col-header[data-col-index="${selectedColIndex}"]`);
    if (!colHeader) return;

    // 1. Ocultar y remover el encabezado de la columna (la letra A, B, C...)
    colHeader.remove();

    // 2. Iterar sobre todas las filas y eliminar la celda correspondiente en esa columna
    const rows = document.getElementById('spreadsheet').querySelectorAll('tbody tr');
    rows.forEach(row => {
        // Buscar el TD que corresponde a esta columna (el índice es relativo al tbody)
        const cellToRemove = row.querySelector(`td:nth-child(${selectedColIndex + 2})`);
        if (cellToRemove) {
            cellToRemove.remove();
        }
    });

    // Resetear el estado de selección
    selectedColIndex = null;
    console.log(`Columna ${colHeader.innerText} eliminada exitosamente.`);
}


/**
 * Initializes the application of spreadsheet features, including column selection listeners.
 */
function initializeSpreadsheet() {
    console.log("Inicializando Hoja de Cálculo...");
    loadDataFromLocalStorage(); // Cargar datos antes de configurar listeners
    setupCellEditing();
    // Llamar a la nueva función para manejar la selección y ocultación de filas
    setupRowHidingListeners(); 
    // Inicializar el listener de selección de columnas
    setupColumnSelectionListener();
}

// Llamada principal para arrancar la aplicación
initializeSpreadsheet();
