function getCoordinates(cellId) {
    if (!cellId) return [null, null];
    const match = cellId.match(/row-(\d+)/);
    let row = match ? parseInt(match[1]) : null;

    const colMatch = cellId.match(/col-([A-Z])/);
    let col = colMatch ? colMatch[1] : null;

    return [row, col];
}

function getCellIdFromCoordinates(row, col) {
    if (isNaN(row) || isNaN(col)) return null;
    // row es 1-based index, col es A=0, B=1...
    const rowIndex = Math.max(1, parseInt(row));
    const colIndex = col.toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);

    if (colIndex < 0 || colIndex >= 26) return null;

    return `row-${rowIndex}col-${String.fromCharCode('A'.charCodeAt(0) + colIndex)}`;
}

function calculateCell(cellElement) {
