        let sum = 0;
        const cellsInRow = Array.from(row.querySelectorAll('td'));
        for (let i = 1; i < cellsInRow.length; i++) {
            const nextCell = cellsInRow[i];
            const textContent = nextCell.textContent.trim();
            if (!isNaN(parseFloat(textContent)) && isFinite(textContent)) {
                sum += parseFloat(textContent);
            }
        }
        cellElement.textContent = sum;
        return true;
    }

    // Lógica de cálculo más compleja podría ir aquí (ej: concatenación, etc.)
