### FUNCION: handleHideColumn
```javascript
function handleHideColumn(columnElement) {
    if (!columnElement || !columnElement.parentElement) {
        console.warn("No se pudo encontrar la columna para manipular.");
        return;
    }

    // Determinar el índice de la columna (0 = A, 1 = B, etc.)
    const colIndex = Array.from(columnElement.parentNode.children).indexOf(columnElement);

    if (colIndex === -1) {
        console.error("No se pudo determinar el índice de la columna.");
        return;
    }

    // 1. Limpiar contenido de todas las celdas en esta columna
    const rows = columnElement.closest('tbody').querySelectorAll('tr');
    rows.forEach(row => {
        // Buscar el TD que corresponde a esta columna (el índice es relativo al tbody)
        // +2 porque la primera celda es el row-label
        const cellToClear = row.querySelector(`td:nth-child(${colIndex + 2})`); 
        if (cellToClear) {
            cellToClear.textContent = ''; // Limpiar contenido
        }
    });

    // 2. Eliminar la columna del DOM (Header y celdas de datos)

    // Eliminar el encabezado de la columna (la letra A, B, C...)
    columnElement.remove(); 

    const tbody = document.querySelector('#spreadsheet tbody');
    if (tbody) {
        // Iterar sobre todas las filas y eliminar la celda correspondiente en esa columna
        const rowsArray = Array.from(tbody.querySelectorAll('tr'));
        rowsArray.forEach(row => {
            const cellToRemove = row.querySelector(`td:nth-child(${colIndex + 2})`);
            if (cellToRemove) {
                cellToRemove.remove();
            }
        });
    }

    // Resetear el estado de selección de columna
    selectedColIndex = null;
    console.log(`Columna ${String.fromCharCode(65 + colIndex)} eliminada exitosamente.`);
}
