```javascript
// Global state variables for selection management (assuming they exist in the original file)
let selectedRowIndex = null;
let selectedColIndex = null;
let selectedRowElement = null; // This variable is managed by setupRowSelectionListener()

/**
 * @typedef {HTMLElement} RowLabelElement
 */

// --- Utility Functions ---

function getCoordinates(cellId) {
    const match = cellId.match(/([A-Z]+)(\d+)/);
    if (!match) return null;
    let colStr = match[1];
    let rowNum = parseInt(match[2]);

    let colIndex = 0;
    for (let i = 0; i < colStr.length; i++) {
        colIndex = colStr.charCodeAt(i) - 'A'.charCodeAt(0);
    }

    return { row: rowNum, col: colIndex };
}

function getCellIdFromCoordinates(row, col) {
    // Row is 1-indexed (e.g., 3), Col is 0-indexed (e.g., 2 for C)
    if (row < 1 || row > 20 || col < 0 || col >= 10) return null;
    const colLetter = String.fromCharCode('A'.charCodeAt(0) + col);
    return `${colLetter}${row}`;
}

function calculateCell(cellElement) {
    // Calculates the cell's coordinates (e.g., A3, B5)
    const cellId = cellElement.getAttribute('data-cell');
    if (!cellId) return null;
    return getCoordinates(cellId);
}

function initializeSpreadsheet() {
    // Setup initial state and listeners
    setupRowSelectionListener();
    setupColumnSelectionAndColoring();
    setupCellEditing();
    setupDeleteButtonListener(); // New listener setup
    loadDataFromLocalStorage();
}


// --- Event Handlers & Logic ---

function handleHideRow(rowElement) {
    if (!rowElement || !rowElement.closest('tr')) {
        console.error("No row element provided or invalid.");
        return;
    }

    const tr = rowElement.closest('tr');
    // 1. Ocultar la fila en el DOM (usando estilo)
    tr.style.display = 'none';

    // Actualizar estado de selección y índices si es necesario
    selectedRowIndex = parseInt(rowElement.getAttribute('data-row-index'));

    console.log(`Fila ${selectedRowIndex + 1} oculta.`);
}

function handleHideColumn(columnElement) {
    if (!columnElement || !columnElement.closest('th')) {
        console.error("No column element provided or invalid.");
        return;
    }

    const th = columnElement.closest('th');
    // 1. Ocultar la columna en el DOM (usando estilo)
    th.style.display = 'none';

    // Actualizar estado de selección y índices si es necesario
    selectedColIndex = parseInt(th.getAttribute('data-col-index'));

    console.log(`Columna ${selectedColIndex + 1} oculta.`);
}


function setupRowSelectionListener() {
    const rowLabels = document.querySelectorAll('.row-label');
    let selectedRowElement = null;

    // Función que maneja la selección de una fila al hacer clic en su etiqueta
    const handleLabelClick = (event) => {
        // Obtener el elemento padre, que es la fila <tr> completa
        const rowElement = event.currentTarget.closest('tr');
        if (rowElement) {
            selectedRowElement = rowElement;
            selectedRowIndex = parseInt(rowElement.getAttribute('data-row-index')); // Update global state
            console.log("Fila seleccionada:", selectedRowElement);
            // Aquí se podría añadir lógica de UI para resaltar la fila
        }
    };

    rowLabels.forEach(label => {
        label.addEventListener('click', handleLabelClick);
    });

    return () => selectedRowElement;
}


function setupColumnSelectionAndColoring() {
    const colHeaders = document.querySelectorAll('.col-header');
    let selectedColElement = null;

    // Función que maneja la selección de una columna al hacer clic en su encabezado
    const handleHeaderClick = (event) => {
        const header = event.currentTarget;
        selectedColElement = header;
        selectedColIndex = parseInt(header.getAttribute('data-col-index')); // Update global state

        // Lógica de coloreado y selección aquí...
        console.log(`Columna ${selectedColIndex + 1} seleccionada.`);
    };

    colHeaders.forEach(header => {
        header.addEventListener('click', handleHeaderClick);
    });
}


function setupCellEditing() {
    const cells = document.querySelectorAll('[contenteditable="true"]');
    cells.forEach(cell => {
        cell.addEventListener('blur', (e) => {
            // Lógica de guardado al perder foco
            console.log(`Contenido de ${e.target.getAttribute('data-cell')} actualizado.`);
            saveCellContent(e.target);
        });
    });
}

function saveCellContent(cellElement) {
    const cellId = cellElement.getAttribute('data-cell');
    if (!cellId) return;
    localStorage.setItem(`cell_${cellId}`, cellElement.textContent);
}


// --- Deletion Logic (R7) ---

/**
 * Borra el contenido y elimina físicamente la fila del DOM.
 * @param {RowLabelElement} rowElement - El elemento de etiqueta de la fila seleccionada.
 */
function handleDeleteRow(rowElement) {
    if (!rowElement || !rowElement.closest('tr')) {
        console.error("No row element provided or invalid.");
        return;
    }

    // 1. Borrar el contenido y limpiar estilos de todas las celdas
    const cells = rowElement.querySelectorAll('td');
    cells.forEach(cell => {
        // Limpia texto y guarda estado original para restaurar si es necesario, pero aquí solo limpiamos.
        cell.textContent = ''; 
        cell.setAttribute('contenteditable', 'true'); // Asegura que siga siendo editable
        // Resetear color de fondo al borrar contenido
        cell.style.backgroundColor = ''; 
    });

    // 2. Borrar físicamente la fila del DOM (Borrar la fila)
    const rowToRemove = rowElement.closest('tr');
    rowToRemove.remove();

    // Resetear el estado de selección después de borrar
    selectedRowIndex = null;
    selectedRowElement = null;
}

/**
 * @description Configura un listener para el botón "Borrar Fila" que utiliza la selección actual.
 */
function setupDeleteButtonListener() {
    const deleteButton = document.getElementById('deleteRowButton');
    if (deleteButton) {
        deleteButton.addEventListener('click', () => {
            // Obtenemos el elemento de etiqueta seleccionado usando la función de selección
            const selectedLabelElement = setupRowSelectionListener(); 
            if (selectedLabelElement) {
                handleDeleteRow(selectedLabelElement);
            } else {
                alert("Por favor, selecciona una fila antes de borrar.");
            }
        });
    }
}


// --- Initialization & Data Loading ---

function loadDataFromLocalStorage() {
    const cells = document.querySelectorAll('[contenteditable="true"]');
    cells.forEach(cell => {
        const cellId = cell.getAttribute('data-cell');
        const savedContent = localStorage.getItem(`cell_${cellId}`);
        if (savedContent !== null) {
            cell.textContent = savedContent;
        }
    });
}

// Initialize the application when the DOM is fully loaded
document.addEventListener('DOMContentLoaded', initializeSpreadsheet);
