/**
 * Inicializa la hoja de cálculo al cargar.
 */
function initializeSpreadsheet() {
    // Limpiar listeners previos para evitar duplicados
    document.getElementById('spreadsheet').removeEventListener('click', handleCellClick);
    document.querySelectorAll('.row-label').forEach(el => el.removeEventListener('click', setupRowSelectionListener));

    // Asignar listeners globales
    setupCellEditing();
    setupColumnSelectionAndColoring();
    setupRowSelectionListener();
    setupRowHidingListeners();

    loadDataFromLocalStorage();
}

/**
 * Obtiene las coordenadas (fila, columna) de una celda dada su ID.
 * @param {string} cellId - El ID de la celda (ej: A1).
 * @returns {{row: number, col: number}} Las coordenadas.
 */
function getCoordinates(cellId) {
    const match = cellId.match(/([A-Z]+)(\d+)/);
    if (!match) return null;

    let columnStr = match[1];
    let rowNum = parseInt(match[2]);

    // Convertir letras a índice de columna (0-based)
    let colIndex = 0;
    for (let i = 0; i < columnStr.length; i++) {
        colIndex = colIndex * 26 + (columnStr.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
        colIndex--; // Ajustar a 0-based index
    }

    return { row: rowNum, col: colIndex };
}

/**
 * Obtiene el ID de la celda dado un par de coordenadas (fila, columna).
 * @param {number} row - Número de fila (1-based).
 * @param {number} col - Índice de columna (0-based).
 * @returns {string} El ID de la celda.
 */
function getCellIdFromCoordinates(row, col) {
    // Columna A=0, B=1...
    const columnLetters = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    if (col < 0 || col >= columnLetters.length) return null;

    return `${columnLetters[col]}${row}`;
}

/**
 * Calcula la posición de una celda dentro del DOM, dado su elemento.
 * @param {HTMLElement} cellElement - El TD o TH que representa la celda.
 * @returns {{rowIndex: number, colIndex: number}} Índice de fila y columna (0-based).
 */
function calculateCell(cellElement) {
    const row = cellElement.closest('tr');
    if (!row) return { rowIndex: -1, colIndex: -1 };

    // El índice del TD dentro de la TR es el índice de columna relativo al tbody/thead
    let colIndex = Array.from(row.querySelectorAll('th, td')).indexOf(cellElement);

    return { rowIndex: row.id.replace('row-', '') - 1, colIndex: colIndex };
}

/**
 * Carga los datos de la hoja de cálculo desde el LocalStorage y actualiza el DOM.
 */
function loadDataFromLocalStorage() {
    const savedData = JSON.parse(localStorage.getItem('spreadsheetData')) || {};
    if (!savedData) return;

    // Limpiar contenido existente antes de cargar
    document.getElementById('spreadsheet').querySelector('tbody').innerHTML = '';

    for (let i = 1; i <= 20; i++) {
        const rowId = `row-${i}`;
        const rowElement = document.createElement('tr');
        rowElement.id = rowId;

        // Añadir el label de fila
        const labelCell = document.createElement('th');
        labelCell.className = 'row-label';
        labelCell.setAttribute('data-row-index', i - 1);
        labelCell.textContent = i;
        rowElement.appendChild(labelCell);

        // Añadir celdas de datos (A, B, C...)
        for (let j = 0; j < 10; j++) {
            const cellId = getCellIdFromCoordinates(i, j);
            const td = document.createElement('td');
            td.setAttribute('contenteditable', 'true');
            td.setAttribute('data-cell', cellId);
            td.id = `cell-${cellId}`; // Añadir ID para fácil referencia
            rowElement.appendChild(td);
        }
        document.getElementById('spreadsheet').querySelector('tbody').appendChild(rowElement);
    }

    // Rellenar datos en las celdas
    for (const cellId in savedData) {
        if (savedData[cellId] !== null && savedData[cellId] !== undefined) {
            const element = document.querySelector(`[data-cell="${cellId}"]`);
            if (element) {
                element.textContent = savedData[cellId];
                // Aplicar color si está guardado
                if (savedData[`color_${cellId}`]) {
                    element.style.backgroundColor = savedData[`color_${cellId}`];
                }
            }
        }
    }

    console.log("Datos cargados exitosamente desde LocalStorage.");
}


/**
 * Configura los listeners de eventos para la edición de celdas (input).
 */
function setupCellEditing() {
    const spreadsheet = document.getElementById('spreadsheet');
    // Usamos event delegation en el tbody para capturar ediciones en cualquier celda editable
    spreadsheet.querySelector('tbody').addEventListener('input', handleCellEdit);
}

/**
 * Maneja la edición de contenido en una celda. Guarda los datos y colores automáticamente.
 * @param {Event} e - El evento de input.
 */
function handleCellEdit(e) {
    const target = e.target;
    if (target.tagName !== 'TD' || !target.hasAttribute('data-cell')) return;

    const cellId = target.getAttribute('data-cell');
    const newValue = target.textContent.trim();
    const colorValue = target.style.backgroundColor;

    // 1. Actualizar LocalStorage con el nuevo valor
    let data = JSON.parse(localStorage.getItem('spreadsheetData')) || {};
    data[cellId] = newValue;
    data[`color_${cellId}`] = colorValue;
    localStorage.setItem('spreadsheetData', JSON.stringify(data));

    // 2. Actualizar el estado de la aplicación (si es necesario)
}


/**
 * Maneja clics en cualquier celda para seleccionar y actualizar coordenadas/estado.
 * @param {Event} e - El evento de clic.
 */
function handleCellClick(e) {
    const target = e.target;
    if (!target.hasAttribute('data-cell')) return;

    // Deseleccionar cualquier elemento previamente seleccionado
    document.querySelectorAll('.selected-cell').forEach(el => el.classList.remove('selected-cell'));

    // Seleccionar la nueva celda
    target.classList.add('selected-cell');

    const cellId = target.getAttribute('data-cell');
    const coords = getCoordinates(cellId);

    if (coords) {
        selectedRowIndex = coords.row; // 0-based index for row label data attribute
        selectedColIndex = coords.col; // 0-based index for column header data attribute
        console.log(`Celda seleccionada: ${cellId} | Fila Index: ${selectedRowIndex}, Col Index: ${selectedColIndex}`);

        // Actualizar el color del selector de color si es necesario (opcional)
    } else {
        selectedRowIndex = null;
        selectedColIndex = null;
    }
}


/**
 * Configura los listeners para la selección y coloreado de columnas.
 */
function setupColumnSelectionAndColoring() {
    const headers = document.querySelectorAll('.col-header');
    headers.forEach(header => {
        header.addEventListener('click', function() {
            // Deseleccionar todos los encabezados
            document.querySelectorAll('.col-header').forEach(h => h.classList.remove('selected-column'));

            // Seleccionar el actual
            this.classList.add('selected-column');

            const colIndex = parseInt(this.getAttribute('data-col-index'));
            selectedColIndex = colIndex;
            console.log(`Columna seleccionada: ${String.fromCharCode(65 + colIndex)} | Col Index: ${colIndex}`);
        });
    });
}

/**
 * Configura los listeners para la selección de filas (clic en el row-label).
 */
function setupRowSelectionListener() {
    const rowLabels = document.querySelectorAll('.row-label');
    rowLabels.forEach(label => {
        // Usamos un listener que se añade al inicio, pero lo reasigna para asegurar la funcionalidad
        label.addEventListener('click', function() {
            // Deseleccionar todos los labels de fila
            document.querySelectorAll('.row-label').forEach(l => l.classList.remove('selected-row'));

            // Seleccionar el actual
            this.classList.add('selected-row');

            const rowIndex = parseInt(this.getAttribute('data-row-index'));
            selectedRowIndex = rowIndex;
            console.log(`Fila seleccionada: ${rowIndex + 1} | Row Index: ${rowIndex}`);
        });
    });
}


