}


/**
 * Oculta una fila completa basada en su elemento label.
 * @param {HTMLElement} rowLabelElement - El TH con la etiqueta de la fila seleccionada.
 */
function handleHideRow(rowLabelElement) {
    if (!rowLabelElement) {
        console.warn("No se pudo encontrar el label de la fila para ocultar.");
        return;
    }

    const rowIndex = parseInt(rowLabelElement.getAttribute('data-row-index'));
    const rowId = `row-${rowIndex + 1}`;
    const rowElement = document.getElementById(rowId);

    if (rowElement) {
        // Ocultar visualmente la fila completa
        rowElement.style.display = 'none';
        console.log(`Fila ${rowIndex + 1} oculta.`);
    } else {
        console.error("No se encontró el elemento de la fila con ID:", rowId);
    }
}

/**
 * Oculta una columna completa basada en su encabezado (letra).
 * @param {HTMLElement} columnElement - El TH del encabezado de la columna seleccionada.
 */
function handleHideColumn(columnElement) {
    if (!columnElement || !columnElement.parentElement) {
        console.warn("No se pudo encontrar la columna para ocultar.");
        return;
    }

    // 1. Determinar el índice de la columna (0 = A, 1 = B, etc.)
    const colIndex = Array.from(columnElement.parentNode.children).indexOf(columnElement);

    // 2. Eliminar el encabezado de la columna (la letra A, B, C...)
    columnElement.remove();

    // 3. Iterar sobre todas las filas y eliminar la celda correspondiente en esa columna
    const rows = columnElement.closest('tbody').querySelectorAll('tr');
    rows.forEach(row => {
        // Buscar el TD que corresponde a esta columna (el índice es relativo al tbody)
        // +2 porque la primera celda es el row-label
        const cellToHide = row.querySelector(`td:nth-child(${colIndex + 2})`); 
        if (cellToHide) {
            cellToHide.remove();
        }
    });

    // Nota: En una implementación completa, aquí se debería actualizar el estado global de columnas y reajustar índices.
}


/**
 * Borra completamente una fila basada en su elemento label.
 * @param {HTMLElement} rowLabelElement - El TH con la etiqueta de la fila seleccionada.
 */
function handleDeleteRow(rowLabelElement) {
    if (!rowLabelElement) {
        console.warn("No se pudo encontrar el label de la fila para borrar.");
        return;
    }

    const rowIndex = parseInt(rowLabelElement.getAttribute('data-row-index'));
    const rowId = `row-${rowIndex + 1}`;
    const rowElement = document.getElementById(rowId);

    if (rowElement) {
        // Eliminar la fila completa del DOM
        rowElement.remove();
        console.log(`Fila ${rowIndex + 1} borrada.`);

        // Aquí se debería actualizar el estado global de filas y reajustar índices.
    } else {
        console.error("No se encontró el elemento de la fila con ID:", rowId);
    }
}
