        // Opcional: Resetear color de fondo al borrar contenido, si es necesario para la UX
        cell.style.backgroundColor = ''; 
    });

    // 2. Borrar físicamente la fila del DOM (Borrar la fila)
    const rowToRemove = rowElement.closest('tr');
    if (rowToRemove) {
        rowToRemove.remove();
    }
}
